import { test, expect } from '@playwright/test';

test.describe('File Upload Error States', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('about:blank');
    await page.setContent(`
      <html>
        <body>
          <h1>File Upload</h1>
          <form id="uploadForm">
            <input type="file" id="fileInput" accept=".jpg,.png,.pdf" />
            <button type="submit">Upload File</button>
          </form>
          <div id="errorMessage" style="display:none; color:red;"></div>
          <div id="successMessage" style="display:none; color:green;"></div>
        </body>
      </html>
    `);

    await page.evaluate(() => {
      const form = document.getElementById('uploadForm') as HTMLFormElement;
      const fileInput = document.getElementById('fileInput') as HTMLInputElement;
      const errorMessage = document.getElementById('errorMessage') as HTMLDivElement;
      const successMessage = document.getElementById('successMessage') as HTMLDivElement;

      form.addEventListener('submit', (e) => {
        e.preventDefault();
        errorMessage.style.display = 'none';
        successMessage.style.display = 'none';

        if (!fileInput.files || fileInput.files.length === 0) {
          errorMessage.textContent = 'Please select a file';
          errorMessage.style.display = 'block';
          return;
        }

        const file = fileInput.files[0];
        const supportedTypes = ['image/jpeg', 'image/png', 'application/pdf'];
        const supportedExtensions = ['.jpg', '.jpeg', '.png', '.pdf'];

        const hasValidExtension = supportedExtensions.some(ext =>
          file.name.toLowerCase().endsWith(ext)
        );

        if (!supportedTypes.includes(file.type) || !hasValidExtension) {
          errorMessage.textContent = `Error: File type "${file.name.split('.').pop()}" is not supported. Supported types: JPG, PNG, PDF`;
          errorMessage.style.display = 'block';
          return;
        }

        successMessage.textContent = `File "${file.name}" uploaded successfully`;
        successMessage.style.display = 'block';
      });
    });
  });

  test('should display error when uploading unsupported file type', async ({ page }) => {
    const fileInput = page.locator('#fileInput');
    const errorMessage = page.locator('#errorMessage');

    const unsupportedFile = 'test.txt';
    await fileInput.setInputFiles({
      name: unsupportedFile,
      mimeType: 'text/plain',
      buffer: Buffer.from('This is a text file'),
    });

    const submitButton = page.getByRole('button', { name: 'Upload File' });
    await submitButton.click();

    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('not supported');
    await expect(errorMessage).toContainText('txt');
  });

  test('should display error for unsupported image format', async ({ page }) => {
    const fileInput = page.locator('#fileInput');
    const errorMessage = page.locator('#errorMessage');

    const unsupportedFile = 'image.bmp';
    await fileInput.setInputFiles({
      name: unsupportedFile,
      mimeType: 'image/bmp',
      buffer: Buffer.from('BM'),
    });

    const submitButton = page.getByRole('button', { name: 'Upload File' });
    await submitButton.click();

    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('not supported');
    await expect(errorMessage).toContainText('bmp');
  });

  test('should successfully upload supported file type', async ({ page }) => {
    const fileInput = page.locator('#fileInput');
    const successMessage = page.locator('#successMessage');
    const errorMessage = page.locator('#errorMessage');

    const supportedFile = 'document.pdf';
    await fileInput.setInputFiles({
      name: supportedFile,
      mimeType: 'application/pdf',
      buffer: Buffer.from('%PDF-1.4'),
    });

    const submitButton = page.getByRole('button', { name: 'Upload File' });
    await submitButton.click();

    await expect(successMessage).toBeVisible();
    await expect(successMessage).toContainText('uploaded successfully');
    await expect(errorMessage).not.toBeVisible();
  });

  test('should display error when no file is selected', async ({ page }) => {
    const errorMessage = page.locator('#errorMessage');

    const submitButton = page.getByRole('button', { name: 'Upload File' });
    await submitButton.click();

    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('Please select a file');
  });
});
